    enum class PersonaKind : uint8_t
    {
        Named,                                 // one fixed display (the first), its own lines
        Generic,                               // a random display and recipe, lines from its pool
        Child,                                 // a generic child: pool K, never during the Rush
        Group                                  // a Rush group: groupSize members, the first says the order line
    };

    struct Persona
    {
        uint32_t entry;
        uint8_t cafeId;
        std::string_view name;
        PersonaKind kind;
        bool child;                            // never during the Rush (also the named children)
        bool enabled;
        char gender;                           // m or f for named personas, else '-'
        uint8_t patiencePct;
        uint8_t tipPct;
        uint8_t minLevel, maxLevel;
        uint8_t displayCount;
        std::array<uint32_t, MaxDisplays> displays;   // 0 = none yet (the persona stays disabled)
        uint8_t favCount;
        std::array<uint8_t, MaxFavourites> fav;        // archetype numbers n; a group's member i orders fav[i]
        uint8_t groupSize;
        char pool;                             // A, H or K: generic lines (and a group's other members), else '-'
        std::string_view order;                // own lines (named and groups), else empty
        std::string_view thanks;
        std::string_view complaint;            // "emote:..." is a text emote
    };

